import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-microbiology-antimicrobials-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Why do incomplete antibiotic courses promote resistance?`]: {
    question: r`Before treatment, about 1 cell in a million in an infecting population is less susceptible to the prescribed drug. The patient takes only the first few doses and stops. Compared with before treatment, the fraction of less susceptible cells among the survivors is expected to be:`,
    options: [r`Lower than before, because the resistant variants were killed first`, r`Higher than before, because the most susceptible cells were killed first`, r`Higher than before, because the drug caused each survivor to mutate`, r`Same as before, because the drug kills all variants at an equal rate`],
    correctAnswer: 1,
    explanation: r`The first doses remove the most susceptible cells, so the variants that were already less susceptible make up a larger share of what regrows. The drug selects among existing variants; it does not make each survivor mutate, and it does not kill all variants equally or kill resistant ones first.`,
  },
  [r`How do beta-lactams (penicillins) kill bacteria?`]: {
    question: r`Growing bacteria are exposed to penicillin and then burst in ordinary dilute medium. Analysis of their cell walls shows glycan strands of normal length. Which wall feature is missing?`,
    options: [r`Glycosidic bonds joining the sugars within each strand`, r`Teichoic acids threading through the strands of the wall`, r`Peptide cross-links between neighboring glycan strands`, r`Lipid A anchors holding the strands to the membrane`],
    correctAnswer: 2,
    explanation: r`Penicillins inhibit the transpeptidase that joins the peptide side chains of neighboring strands, so the wall lacks cross-links and cannot resist osmotic pressure. The sugar backbone is built by a different activity, and teichoic acids and lipid A are not what a beta-lactam blocks.`,
  },
  [r`Why do many antibiotics target the ribosome selectively?`]: {
    question: r`A new drug binds a groove found on the bacterial 30S subunit but absent from the human 40S subunit. In cell-free translation systems, which result is expected?`,
    options: [r`Bacterial translation stops; human cytoplasmic translation continues`, r`Bacterial translation continues; human cytoplasmic translation stops`, r`Both bacterial and human cytoplasmic translation stop to the same degree`, r`Neither bacterial nor human cytoplasmic translation is affected at all`],
    correctAnswer: 0,
    explanation: r`Bacterial 70S ribosomes (30S + 50S) differ structurally from human cytoplasmic 80S ribosomes (40S + 60S), so a drug that fits only the bacterial subunit stops only bacterial translation. The reversed answer swaps the two ribosome types, and the other two ignore the structural difference that gives selectivity.`,
  },
  [r`Why is combination therapy used for tuberculosis?`]: {
    question: r`A patient with active tuberculosis is given four drugs together for months instead of one drug for ten days. Which pair of reasons best justifies this plan?`,
    options: [r`A cell resistant to any one drug is very unlikely, and the bacilli grow quickly`, r`Each drug alone cannot reach its MIC in the lung, and the bacilli grow quickly`, r`Each drug covers a different co-infecting species, and the bacilli grow slowly`, r`A cell resistant to every drug at once is very unlikely, and the bacilli grow slowly`],
    correctAnswer: 3,
    explanation: r`Single-drug resistant mutants are common enough in a large population, but a cell resistant to all the drugs at once is extremely improbable, and the slow growth of the bacilli demands a long course. The wrong choices claim fast growth, claim single-drug resistance is rare, or invent several co-infecting species.`,
  },
  [r`Contrast bactericidal and bacteriostatic drugs.`]: {
    question: r`Two flasks each start with 10⁶ viable bacteria per mL. After 6 hours with drug X the count is still 10⁶ per mL, and growth resumes when X is washed out. After 6 hours with drug Y the count is 10² per mL. How should the drugs be classified?`,
    options: [r`X is bactericidal and Y is bacteriostatic`, r`Both X and Y are bacteriostatic drugs`, r`X is bacteriostatic and Y is bactericidal`, r`Both X and Y are bactericidal drugs`],
    correctAnswer: 2,
    explanation: r`X holds the count steady without killing, and the cells regrow once it is removed, which is bacteriostatic. Y reduces the viable count ten thousandfold, which is killing, so it is bactericidal. The other choices swap the two terms or ignore the difference between a stable count and a falling one.`,
  },
  [r`Name the main mechanisms of antibiotic resistance.`]: {
    question: r`An isolate is resistant to ciprofloxacin. The drug enters the cells normally, is not pumped out, and is recovered chemically intact, but the isolate's DNA gyrase has an amino acid change that weakens drug binding. Which resistance mechanism is this?`,
    options: [r`Target modification`, r`Enzymatic inactivation`, r`Active drug efflux`, r`Reduced permeability`],
    correctAnswer: 0,
    explanation: r`The drug is unchanged and reaches its site, but the protein it must bind has been altered, which is target modification. Enzymatic inactivation would leave a chemically changed drug, efflux would lower the amount inside the cell, and reduced permeability would slow entry; the stem rules out all three.`,
  },
  [r`Why are antibiotics ineffective against viruses?`]: {
    question: r`A patient with a common cold caused by a rhinovirus asks for amoxicillin, a cell-wall synthesis inhibitor. Why would the drug not shorten the illness?`,
    options: [r`The virus pumps the drug out faster than it can enter`, r`The virus has no peptidoglycan wall for the drug to act on`, r`The virus makes a beta-lactamase that opens the drug's ring`, r`The virus hides its peptidoglycan wall inside host cells`],
    correctAnswer: 1,
    explanation: r`Viruses have no cell wall, no ribosomes and no metabolism of their own, so a drug aimed at peptidoglycan synthesis has nothing to act on. Efflux pumps and beta-lactamases are bacterial resistance mechanisms, and a virus has no peptidoglycan to hide.`,
  },
  [r`What does MIC mean?`]: {
    question: r`Drug P has an MIC of 0.5 μg/mL against isolate A and 16 μg/mL against isolate B. Safe dosing gives blood levels of about 4 μg/mL. Which infection is expected to respond to drug P?`,
    options: [r`Isolate B only, since a higher MIC means greater sensitivity`, r`Both isolates, since any measurable MIC means susceptibility`, r`Neither isolate, since blood levels must stay below the MIC`, r`Isolate A only, since blood levels exceed its MIC but not B's`],
    correctAnswer: 3,
    explanation: r`The MIC is the lowest concentration that prevents visible growth, so a drug works only where achievable levels exceed it: 4 is above 0.5 but below 16. A higher MIC means less sensitivity, not more. Every isolate has some MIC, and levels must be above it, not below.`,
  },
  [r`During log phase, population growth is:`]: {
    question: r`A culture in log phase doubles every 20 minutes and contains 1000 cells. If it stays in log phase, how many cells are present 1 hour later?`,
    options: [r`3000 cells`, r`4000 cells`, r`6000 cells`, r`8000 cells`],
    correctAnswer: 3,
    explanation: r`Log-phase growth is exponential: one hour is three doublings, so 1000 → 2000 → 4000 → 8000. Adding 1000 per doubling (4000) or multiplying by the number of doublings (3000, or 6000 from 2 × 3) treats the growth as linear.`,
  },
  [r`Horizontal gene transfer contributes to antibiotic resistance because it:`]: {
    question: r`Within weeks, a resistance gene with an identical DNA sequence is found in E. coli and in an unrelated Gram-positive species living in the same patient's gut. What is the best explanation?`,
    options: [r`A mobile element carried the gene across species lines`, r`Each species inherited it from a shared ancestral cell`, r`Both species mutated the same bases independently`, r`The drug induced the same gene to form in each species`],
    correctAnswer: 0,
    explanation: r`An identical gene appearing quickly in unrelated species points to horizontal transfer on a plasmid or other mobile element. Vertical inheritance from a common ancestor would show sequence divergence, identical independent mutations across a whole gene are implausible, and drugs select for genes rather than create them.`,
  },
  [r`A virulence factor is:`]: {
    question: r`A pneumococcal mutant that cannot make its capsule grows as fast as the parent strain in broth, but in a host it is quickly engulfed by phagocytes and causes no illness. How is the capsule best classified?`,
    options: [r`A housekeeping trait, since it is needed for basic cell growth`, r`A resistance factor, since it blocks the entry of antibiotics`, r`A virulence factor, since it aids disease but not basic growth`, r`A commensal trait, since it mainly benefits the infected host`],
    correctAnswer: 2,
    explanation: r`A virulence factor is a trait that improves a pathogen's ability to cause disease, here by letting the cell evade phagocytes, without being needed for growth itself. Normal growth in broth rules out a housekeeping role, no antibiotic is involved, and the capsule helps the pathogen, not the host.`,
  },
  [r`The normal microbiota benefits the host by:`]: {
    question: r`Germ-free mice, raised with no intestinal bacteria, become infected by an oral dose of an intestinal pathogen far smaller than the dose needed to infect ordinary mice. What best explains the difference?`,
    options: [r`Resident bacteria normally secrete the antibodies that bind the pathogen`, r`Resident bacteria normally compete with the pathogen for nutrients and space`, r`Resident bacteria normally supply the pathogen with nutrients and space`, r`Resident bacteria normally engulf the pathogen as phagocytes in the gut`],
    correctAnswer: 1,
    explanation: r`The normal microbiota occupies attachment sites and uses up nutrients, so an incoming pathogen struggles to establish itself; without that competition a small dose is enough. Bacteria do not make antibodies or act as phagocytes, and supplying the pathogen would make ordinary mice the easier target.`,
  },
  [r`Chloramphenicol inhibits the {{c1::peptidyl transferase}} center of the 50S subunit.`]: {
    question: r`A bacterial ribosome is exposed to chloramphenicol. A charged tRNA still enters the A site normally. What is observed next?`,
    options: [r`The peptide stays on the P-site tRNA and no new peptide bond forms`, r`The peptide moves to the A-site tRNA but the ribosome cannot shift`, r`The 30S subunit misreads the codon and adds a wrong amino acid`, r`The 50S subunit falls away from the 30S subunit at the start codon`],
    correctAnswer: 0,
    explanation: r`Chloramphenicol blocks the peptidyl transferase center of the 50S subunit, so the growing chain cannot be joined to the incoming amino acid and stays on the P-site tRNA. A peptide that transfers but cannot shift describes a translocation block, misreading describes aminoglycosides, and subunit joining is an initiation step.`,
  },
  [r`Why does the folate pathway offer selective toxicity even though humans also require folate?`]: {
    question: r`A compound that completely blocks dihydropteroate synthase is added to cultured human cells growing in medium that contains folate. What effect is expected on the human cells?`,
    options: [r`Death, because human cells need this enzyme to import folate`, r`Death, because human cells make folate from PABA as bacteria do`, r`None, because human cells have no need for folate cofactors`, r`None, because human cells lack this enzyme and import folate`],
    correctAnswer: 3,
    explanation: r`Humans do not synthesize folate; they take it up from the diet, so the synthesis enzyme is absent and blocking it does nothing to human cells. Humans do need folate cofactors, which is why the answer must rest on import, and the enzyme plays no part in folate uptake.`,
  },
  [r`Define bacteriostatic versus bactericidal, and name settings where a cidal drug is essential.`]: {
    question: r`Four patients have infections caused by organisms that test susceptible to a bacteriostatic drug. For which patient is a bactericidal drug most clearly required instead?`,
    options: [r`A healthy adult with an uncomplicated bladder infection`, r`A healthy teenager with a mild skin infection on one arm`, r`A chemotherapy patient with fever and almost no neutrophils`, r`A healthy adult with a mild sinus infection of recent onset`],
    correctAnswer: 2,
    explanation: r`A bacteriostatic drug only stops growth and leaves the immune system to clear the organisms, so it fails when phagocytes are missing, as in the neutropenic patient. The three healthy patients with mild infections have working immune defenses that can finish the job.`,
  },
  [r`For a bacteriostatic drug, the MBC is far {{c1::higher}} than the MIC.`]: {
    question: r`A drug is described as bacteriostatic against an isolate whose MIC is 0.5 μg/mL. Which MBC for that isolate is most consistent with this description?`,
    options: [r`0.25 μg/mL`, r`0.5 μg/mL`, r`1 μg/mL`, r`32 μg/mL`],
    correctAnswer: 3,
    explanation: r`A bacteriostatic drug stops growth at a low concentration but kills 99.9 percent of cells only at a much higher one, so the MBC lies far above the MIC, here 64 times higher. An MBC equal to or twice the MIC describes a bactericidal drug, and an MBC cannot be lower than the MIC.`,
  },
  [r`Why can adding tetracycline antagonize the killing effect of a beta-lactam given simultaneously?`]: {
    question: r`Penicillin alone kills 99.9 percent of a growing culture in a few hours. When tetracycline is added at the same time, far fewer cells die. What best explains the loss of killing?`,
    options: [r`Tetracycline binds penicillin in solution, so less free drug reaches the wall`, r`Tetracycline halts growth, so cells stop the wall synthesis penicillin exploits`, r`Tetracycline induces a lactamase, so penicillin is hydrolyzed in the medium`, r`Tetracycline closes the porins, so penicillin cannot reach the periplasm`],
    correctAnswer: 1,
    explanation: r`Beta-lactams kill only cells that are actively building wall as they grow. Tetracycline stops protein synthesis and growth, so wall remodeling stops and penicillin loses its lethal window. Tetracycline does not bind penicillin, induce a lactamase or close porins.`,
  },
  [r`How does porin loss protect Gram-negative bacteria from hydrophilic antibiotics?`]: {
    question: r`A mutant E. coli has lost its major outer-membrane porin. What change is expected for a small hydrophilic antibiotic that acts in the periplasm?`,
    options: [r`Slower entry across the outer membrane, so a higher MIC`, r`Faster entry across the outer membrane, so a lower MIC`, r`Faster export across the inner membrane, so a higher MIC`, r`Slower hydrolysis within the periplasm, so a lower MIC`],
    correctAnswer: 0,
    explanation: r`Hydrophilic drugs cross the Gram-negative outer membrane through porin channels, so fewer porins mean less drug inside and a higher MIC. Losing a channel cannot speed entry, and porins are neither efflux pumps nor drug-hydrolyzing enzymes.`,
  },
  [r`Why does zidovudine (an NRTI) terminate reverse transcription after being incorporated?`]: {
    question: r`A chemist alters zidovudine so that the analog carries a normal 3'-hydroxyl group. What happens to its ability to terminate DNA chains made by reverse transcriptase?`,
    options: [r`It is kept, because the base still mispairs with the RNA template`, r`It is kept, because reverse transcriptase stays bound irreversibly`, r`It is lost, because the next phosphodiester bond can now be formed`, r`It is lost, because host kinases can no longer add any phosphates`],
    correctAnswer: 2,
    explanation: r`Zidovudine stops the chain because it has no 3'-hydroxyl to attack the next nucleotide. Restoring that group lets the next phosphodiester bond form, so termination is lost. The drug does not work by mispairing or by locking the enzyme, and the 3' position is not where kinases add phosphates.`,
  },
  [r`By what enzymatic strategy do many organisms resist aminoglycosides?`]: {
    question: r`An isolate is resistant to gentamicin. Drug recovered from the cells carries an added phosphate group, and ribosomes purified from the isolate bind unmodified gentamicin normally. Which description fits this resistance?`,
    options: [r`Drug inactivation by hydrolysis of a ring in the drug`, r`Drug inactivation by covalent modification of the drug`, r`Target modification by methylation of the 16S rRNA`, r`Target bypass by a second drug-insensitive ribosome`],
    correctAnswer: 1,
    explanation: r`Aminoglycoside-modifying enzymes add acetyl, phosphate or adenylyl groups to the drug so it no longer binds the ribosome; that is inactivation by chemical modification. Hydrolysis is how beta-lactamases work, and normal binding by the isolate's ribosomes rules out a changed or replaced target.`,
  },
  [r`The four general resistance strategies: drug {{c1::inactivation}}, target modification, efflux, and reduced uptake or target bypass.`]: {
    question: r`Which pairing of a resistance example with its general strategy is correct?`,
    options: [r`Altered PBP2a is active drug efflux`, r`Porin loss is target modification`, r`rRNA methylation is target bypass`, r`Beta-lactamase is drug inactivation`],
    correctAnswer: 3,
    explanation: r`Beta-lactamase destroys the drug by opening its ring, which is drug inactivation. Altered PBP2a and rRNA methylation both change the drug's binding site, so they are target modification, and porin loss lowers drug entry, which is reduced uptake.`,
  },
  [r`NNRTIs inhibit reverse transcriptase by binding an {{c1::allosteric pocket}} rather than the active site.`]: {
    question: r`Raising the nucleotide concentration tenfold relieves inhibition of HIV reverse transcriptase by an activated nucleoside analog but has no effect on inhibition by drug N. Where does drug N most likely bind?`,
    options: [r`An allosteric pocket away from the polymerase active site`, r`The nucleotide-binding site, as a competing substrate`, r`The 3' end of the growing DNA, as a chain terminator`, r`The viral RNA template at the primer-binding sequence`],
    correctAnswer: 0,
    explanation: r`Inhibition that extra substrate cannot overcome is non-competitive, which is how NNRTIs act: they bind an allosteric pocket and distort the catalytic site. A competing substrate or chain terminator would be outcompeted by more nucleotide, and NNRTIs do not bind the template.`,
  },
  [r`NRTIs are selective for reverse transcriptase, yet cause mitochondrial side effects. Explain both facts.`]: {
    question: r`After years on a nucleoside reverse transcriptase inhibitor, a patient develops muscle weakness and lactic acidosis, and a muscle biopsy shows depleted mitochondrial DNA. Which off-target interaction explains this?`,
    options: [r`Nuclear DNA polymerase alpha incorporates the analog`, r`Mitochondrial RNA polymerase incorporates the analog`, r`Mitochondrial DNA polymerase gamma incorporates the analog`, r`Cytoplasmic 80S ribosomes are stalled by the analog`],
    correctAnswer: 2,
    explanation: r`Nuclear polymerases largely reject these analogs, which is the source of selectivity, but mitochondrial DNA polymerase gamma accepts some of them, so mitochondrial DNA replication is impaired. The analogs are DNA chain terminators, so RNA polymerase and ribosomes are not their targets.`,
  },
  [r`How does oseltamivir limit influenza spread within a host?`]: {
    question: r`Cultured cells infected with influenza are treated with oseltamivir. Which observation is expected?`,
    options: [r`No viral RNA is copied, so no new virions are assembled`, r`New virions form but stay clumped on the cell surface`, r`Virions bind but cannot fuse with the endosome membrane`, r`New virions leave normally but lack their hemagglutinin`],
    correctAnswer: 1,
    explanation: r`Oseltamivir inhibits neuraminidase, the enzyme that cuts sialic acid so that budding virions can detach. Without it, new virions are made but remain tethered to the cell and to each other. The drug does not block RNA copying, entry or hemagglutinin production.`,
  },
  [r`What enzyme do azole antifungals inhibit, and what accumulates as a result?`]: {
    question: r`Yeast cells are treated with fluconazole, an azole. Which change in the cells' sterols is expected?`,
    options: [r`Ergosterol rises and 14-methylated sterols fall`, r`Cholesterol falls and beta-glucan fragments build up`, r`Ergosterol is unchanged but leaks out through pores`, r`Ergosterol falls and 14-methylated sterols build up`],
    correctAnswer: 3,
    explanation: r`Azoles inhibit lanosterol 14-alpha-demethylase, so the product ergosterol is depleted and the methylated intermediates before the block accumulate. The reversed answer flips substrate and product, pore formation belongs to amphotericin B, and glucan belongs to the cell wall.`,
  },
  [r`Echinocandins inhibit beta-1,3-glucan synthase. Why does this offer better selectivity than most antifungals?`]: {
    question: r`Human cells exposed to an echinocandin at antifungal concentrations show essentially no direct damage. What is the main reason?`,
    options: [r`Human cells have no beta-glucan wall or glucan synthase`, r`Human cells pump the drug out through a membrane carrier`, r`Human cells use cholesterol in place of ergosterol`, r`Human cells have 80S ribosomes in place of 70S ribosomes`],
    correctAnswer: 0,
    explanation: r`Echinocandins block beta-1,3-glucan synthase, which builds a fungal wall polymer that human cells do not have, so the host has no target. The cholesterol and ergosterol difference explains the partial selectivity of membrane-directed antifungals, and fungi have 80S ribosomes too.`,
  },
  [r`Vancomycin blocks wall cross-linking by binding the {{c1::D-Ala-D-Ala}} terminus of peptidoglycan precursors.`]: {
    question: r`Before being added to staphylococci, vancomycin is mixed with a large excess of free D-Ala-D-Ala dipeptide. What happens to its antibacterial activity?`,
    options: [r`It rises, since the dipeptide helps the drug cross the wall`, r`It is unchanged, since the drug binds the transpeptidase`, r`It falls, since the drug is occupied by the free dipeptide`, r`It falls, since the dipeptide hydrolyzes the drug's ring`],
    correctAnswer: 2,
    explanation: r`Vancomycin binds the D-Ala-D-Ala end of the wall precursor, not the enzyme, so free dipeptide soaks up the drug and less is left to cap real precursors. Believing the drug binds the transpeptidase is the common mix-up with beta-lactams, and a dipeptide cannot hydrolyze the drug.`,
  },
  [r`Why are cell-wall synthesis inhibitors among the most selectively toxic antibiotics?`]: {
    question: r`Penicillin can be given at doses many times the minimum effective dose with little mechanism-based harm to the patient. What best explains this wide safety margin?`,
    options: [r`Its target enzymes exist in humans but bind the drug weakly`, r`Its target enzymes build a polymer that human cells never make`, r`Its target enzymes exist only in human mitochondria, not cytosol`, r`Its molecule is too large to enter any human cell or tissue`],
    correctAnswer: 1,
    explanation: r`Peptidoglycan and the penicillin-binding proteins that assemble it exist only in bacteria, so the drug's target is completely absent from the host. A weaker-binding human version describes drugs like trimethoprim, mitochondrial targets explain ribosomal drug toxicity, and size is not the reason.`,
  },
  [r`What two enzymes do fluoroquinolones inhibit, and what cellular catastrophe results?`]: {
    question: r`Growing bacteria are treated with ciprofloxacin. Which DNA lesion accumulates and kills the cells?`,
    options: [r`Thymine dimers where adjacent bases are fused covalently`, r`Chain-terminated strands that lack a 3'-hydroxyl group`, r`Unprimed lagging strands where primase has been blocked`, r`Double-strand breaks at trapped topoisomerase complexes`],
    correctAnswer: 3,
    explanation: r`Fluoroquinolones trap DNA gyrase and topoisomerase IV on DNA they have cut; replication forks hit these complexes and double-strand breaks result, which is why the drugs are bactericidal. Thymine dimers come from UV light, chain termination from nucleoside analogs, and primase is not the target.`,
  },
  [r`How do sulfonamides exploit their structural resemblance to PABA?`]: {
    question: r`Dihydropteroate synthase is assayed with increasing amounts of its substrate PABA, with and without a sulfonamide. How does the sulfonamide change the enzyme's apparent kinetics?`,
    options: [r`Km rises and Vmax is unchanged`, r`Km is unchanged and Vmax falls`, r`Km falls and Vmax also falls`, r`Km rises and Vmax also rises`],
    correctAnswer: 0,
    explanation: r`Sulfonamides resemble PABA and compete with it for the active site, and a competitive inhibitor raises the apparent Km while enough substrate still reaches the same Vmax. An unchanged Km with a lower Vmax is non-competitive inhibition, and both falling is uncompetitive inhibition.`,
  },
  [r`How do beta-lactamases destroy penicillins, and how do clavulanate combinations restore activity?`]: {
    question: r`Against one isolate, amoxicillin alone fails and clavulanate alone has almost no effect, but the two together clear the culture. What is clavulanate doing?`,
    options: [r`It binds the transpeptidase at a second site beside amoxicillin`, r`It opens porins so more amoxicillin reaches the periplasm`, r`It permanently inactivates the lactamase, sparing amoxicillin`, r`It blocks the efflux pump that would remove the amoxicillin`],
    correctAnswer: 2,
    explanation: r`The isolate makes a beta-lactamase that opens amoxicillin's ring. Clavulanate is a suicide substrate that permanently ties up that enzyme, so amoxicillin reaches the transpeptidases intact. Clavulanate has little wall activity of its own and does not act on porins or pumps.`,
  },
  [r`Amphotericin B binds {{c1::ergosterol}} and forms membrane pores that leak ions from fungal cells.`]: {
    question: r`Amphotericin B is added to a suspension of yeast cells. Which change is the first direct result of the drug's action?`,
    options: [r`Ergosterol synthesis stops at the demethylase step`, r`Potassium ions leak out of the cells through new pores`, r`Glucan chains in the cell wall stop being extended`, r`Microtubules of the mitotic spindle fail to assemble`],
    correctAnswer: 1,
    explanation: r`Amphotericin B binds ergosterol already in the membrane and assembles pores, so ions such as potassium leak out. Stopping ergosterol synthesis is the azole mechanism, blocking glucan extension is the echinocandin mechanism, and the drug does not act on microtubules.`,
  },
  [r`What enzymatic step do beta-lactams (penicillins, cephalosporins) block, and why does killing require growing cells?`]: {
    question: r`The same penicillin concentration, well above the MIC, is added to a rapidly dividing log-phase culture and to a non-dividing stationary-phase culture of one strain. What is expected?`,
    options: [r`Log-phase cells lyse; stationary cells largely survive`, r`Stationary cells lyse; log-phase cells largely survive`, r`Both cultures lyse at about the same rate and extent`, r`Neither culture lyses, but both stop making protein`],
    correctAnswer: 0,
    explanation: r`Beta-lactams block the transpeptidase step of wall synthesis, and only cells actively remodeling their wall while dividing become fragile and lyse. Non-dividing cells are not building wall, so they escape. The drug does not act on protein synthesis.`,
  },
  [r`A patient's pneumonia fails to respond to penicillin because the pathogen is Mycoplasma. Why is this failure predictable?`]: {
    question: r`A patient's pneumonia is caused by Mycoplasma. Which drug choice and description of the organism's penicillin resistance are correct?`,
    options: [r`A macrolide; the resistance is acquired, from a mutated target`, r`A cephalosporin; the resistance is intrinsic, from a missing target`, r`Vancomycin; the resistance is acquired, from a new lactamase gene`, r`A macrolide; the resistance is intrinsic, from a missing target`],
    correctAnswer: 3,
    explanation: r`Mycoplasma has no peptidoglycan wall, so every wall-directed drug, including cephalosporins and vancomycin, has nothing to act on, while a ribosome-directed macrolide still works. The resistance is intrinsic because the target was never there, not acquired through mutation or a new gene.`,
  },
  [r`Ribosome-targeted antibiotics are selective because bacteria use 70S ribosomes, yet still cause toxicity. Why?`]: {
    question: r`A drug designed to bind bacterial ribosomes causes some toxicity in human tissues. Which human ribosomes are the most likely off-target site, and why?`,
    options: [r`Rough ER ribosomes, because they make secreted proteins`, r`Mitochondrial ribosomes, because of their bacterial ancestry`, r`Free cytosolic ribosomes, because they are the most numerous`, r`Nucleolar pre-ribosomes, because their rRNA is still unfolded`],
    correctAnswer: 1,
    explanation: r`Mitochondria arose from bacteria by endosymbiosis and keep bacteria-like ribosomes, so drugs aimed at the 70S ribosome can inhibit them. Rough ER and free cytosolic ribosomes are both 80S and are spared, and assembling subunits in the nucleolus are not the binding target.`,
  },
  [r`Why does a bacterium need DNA gyrase during replication, making it a good drug target?`]: {
    question: r`In a replicating bacterium, DNA gyrase is suddenly inhibited while helicase keeps unwinding the DNA. What builds up ahead of the replication fork?`,
    options: [r`Negative supercoils that stall further unwinding`, r`Okazaki fragments that cannot be joined together`, r`Positive supercoils that stall further unwinding`, r`RNA primers that cannot be removed from the DNA`],
    correctAnswer: 2,
    explanation: r`Unwinding at the fork overwinds the DNA ahead of it, creating positive supercoils; gyrase normally removes this strain by adding negative supercoils. Choosing negative supercoils flips the sign, and joining Okazaki fragments or removing primers are jobs of ligase and DNA polymerase I.`,
  },
  [r`Rifampin inhibits bacterial {{c1::DNA-dependent RNA polymerase}}, blocking transcription initiation.`]: {
    question: r`Rifampin is added to growing bacteria. Which process is the first to be affected directly?`,
    options: [r`New RNA chains stop being started; DNA synthesis continues at first`, r`New DNA chains stop being started; RNA synthesis continues at first`, r`New peptide bonds stop forming; RNA synthesis continues at first`, r`New wall cross-links stop forming; RNA synthesis continues at first`],
    correctAnswer: 0,
    explanation: r`Rifampin binds bacterial DNA-dependent RNA polymerase and blocks the start of transcription, so new RNA chains are the first casualty. Protein and wall synthesis decline only later as messages run out, and DNA polymerase is not the drug's target.`,
  },
  [r`Trimethoprim inhibits bacterial {{c1::dihydrofolate reductase}}; pairing it with a sulfonamide gives sequential blockade.`]: {
    question: r`Bacteria are treated with trimethoprim alone. Which change in their folate intermediates is expected?`,
    options: [r`Tetrahydrofolate accumulates; dihydrofolate is depleted`, r`PABA is depleted; dihydropteroate accumulates`, r`Dihydropteroate is depleted; dihydrofolate is depleted`, r`Dihydrofolate accumulates; tetrahydrofolate is depleted`],
    correctAnswer: 3,
    explanation: r`Trimethoprim inhibits dihydrofolate reductase, the step that converts dihydrofolate to tetrahydrofolate, so the substrate builds up and the product runs short. The reversed answer flips substrate and product, and the choices involving dihydropteroate describe the earlier step that sulfonamides block.`,
  },
  [r`Aminoglycosides bind the {{c1::30S}} subunit, causing misreading of mRNA, and are bactericidal.`]: {
    question: r`Bacteria treated with streptomycin produce full-length proteins that carry wrong amino acids at many positions. Which target and overall effect match this drug?`,
    options: [r`30S subunit decoding site; the effect is bacteriostatic`, r`30S subunit decoding site; the effect is bactericidal`, r`50S peptidyl transferase site; the effect is bactericidal`, r`50S peptide exit tunnel; the effect is bacteriostatic`],
    correctAnswer: 1,
    explanation: r`Aminoglycosides bind the 30S subunit and distort decoding, so the message is misread, and the resulting faulty proteins make the effect lethal. Most other ribosome inhibitors are static, which is the trap in the first choice, and the 50S sites belong to chloramphenicol and the macrolides.`,
  },
  [r`Tetracyclines block the ribosomal {{c1::A site}}, preventing aminoacyl-tRNA binding on the 30S subunit.`]: {
    question: r`Bacterial ribosomes are stalled by tetracycline in the middle of making a protein. What is found when they are examined?`,
    options: [r`The A site fills, but no peptide bond forms with its tRNA`, r`The P site stays empty because initiator tRNA cannot bind`, r`The A site stays empty because charged tRNA cannot bind`, r`The E site stays full because the ribosome cannot shift`],
    correctAnswer: 2,
    explanation: r`Tetracyclines bind the 30S subunit and block the A site, so the next aminoacyl-tRNA cannot be delivered. A filled A site with no bond formed describes chloramphenicol, and a ribosome that cannot shift describes a translocation block such as that of the macrolides.`,
  },
  [r`Where do macrolides such as erythromycin act, and what step of elongation do they disrupt?`]: {
    question: r`Ribosomes from bacteria treated with one drug release short peptides still attached to tRNA soon after translation starts. Which drug and binding site explain this?`,
    options: [r`Erythromycin, which sits in the 50S exit tunnel`, r`Gentamicin, which distorts the 30S decoding site`, r`Tetracycline, which occupies the A site on the 30S`, r`Chloramphenicol, which blocks peptidyl transferase`],
    correctAnswer: 0,
    explanation: r`Macrolides bind the 50S subunit in the peptide exit tunnel, so the growing chain cannot advance, translocation fails and short peptidyl-tRNAs drop off. Gentamicin causes misreading of full-length proteins, tetracycline prevents tRNA delivery, and chloramphenicol stops bond formation itself.`,
  },
  [r`How do efflux pumps confer resistance, and why can one pump defeat several drug classes?`]: {
    question: r`An isolate carries a tetracycline efflux pump, yet its ribosomes bind the drug normally. Why does tetracycline fail against it?`,
    options: [r`Its structure is hydrolyzed before it can reach the ribosome`, r`Its binding site on the 30S subunit has been methylated`, r`Its entry through outer-membrane porins has been blocked`, r`Its concentration inside the cell stays below inhibitory levels`],
    correctAnswer: 3,
    explanation: r`An efflux pump actively exports the drug, so too little accumulates inside the cell to inhibit the ribosome even though the target is normal. Hydrolysis is drug inactivation, methylation is target modification, and blocked porins are reduced uptake, which are different mechanisms.`,
  },
  [r`How do vancomycin-resistant enterococci (VRE) modify the drug's binding site?`]: {
    question: r`An enterococcal isolate builds its wall precursors ending in D-Ala-D-Lac and keeps growing in vancomycin. How is this resistance best classified?`,
    options: [r`Drug inactivation; an enzyme cleaves the peptide backbone of vancomycin`, r`Target modification; wall synthesis continues with the new precursor`, r`Reduced uptake; the outer membrane excludes the large glycopeptide`, r`Target bypass; the cell stops making any peptidoglycan altogether`],
    correctAnswer: 1,
    explanation: r`Vancomycin binds the D-Ala-D-Ala end of the precursor, so changing that end to D-Ala-D-Lac alters the drug's binding site while cross-linking carries on, which is target modification. The drug is not cleaved, enterococci are Gram-positive with no outer membrane, and the cell still makes peptidoglycan.`,
  },
  [r`erm-mediated macrolide resistance works by {{c1::methylation of 23S rRNA}} in the 50S subunit.`]: {
    question: r`A staphylococcal isolate carries an erm gene and is reported resistant to erythromycin. Which other drug is most likely to fail, and why?`,
    options: [r`Gentamicin, because its binding site overlaps the methylated site`, r`Vancomycin, because methylation thickens the peptidoglycan layer`, r`Clindamycin, because its binding site overlaps the methylated site`, r`Clindamycin, because the same enzyme hydrolyzes both drug classes`],
    correctAnswer: 2,
    explanation: r`The erm methylase modifies 23S rRNA in the 50S subunit where macrolides and clindamycin both bind, so one change lowers affinity for both. Gentamicin binds the 30S subunit, vancomycin acts on the wall, and the mechanism changes the target and does not hydrolyze any drug.`,
  },
  [r`What step do HIV protease inhibitors ('-navir' drugs) block, and what particles result?`]: {
    question: r`HIV-infected cells are treated with a protease inhibitor. What is observed?`,
    options: [r`Virions bud, but hold uncleaved Gag polyprotein and cannot infect`, r`Virions cannot bud, because the Gag polyprotein is never translated`, r`Viral DNA is not made, because reverse transcription stops early`, r`Viral DNA is made, but cannot be inserted into a host chromosome`],
    correctAnswer: 0,
    explanation: r`The viral protease cuts the Gag and Gag-Pol polyproteins during maturation. With it blocked, particles still bud but stay immature and noninfectious. Halting DNA synthesis describes reverse transcriptase inhibitors, and blocking insertion describes integrase inhibitors.`,
  },
  [r`Acyclovir is activated only in infected cells because the first phosphorylation requires {{c1::viral thymidine kinase}}.`]: {
    question: r`Acyclovir enters both herpes-infected and uninfected cells of a patient. Why is DNA synthesis in the uninfected cells spared?`,
    options: [r`They lack the membrane carrier that lets the drug enter cells`, r`They have a repair enzyme that restores the missing 3'-hydroxyl`, r`They have a DNA polymerase that cannot bind any guanosine analog`, r`They lack the viral kinase that adds the drug's first phosphate`],
    correctAnswer: 3,
    explanation: r`Acyclovir becomes an active chain terminator only after it is phosphorylated, and the first phosphate is added by the viral thymidine kinase found only in infected cells. The stem states that the drug enters both cell types, and no enzyme restores a 3'-hydroxyl to the analog.`,
  },
  [r`MRSA resists all classic beta-lactams via {{c1::an altered penicillin-binding protein (PBP2a, encoded by mecA)}}.`]: {
    question: r`A Staphylococcus aureus isolate from a wound is found to carry the mecA gene. Which treatment choice and reasoning are appropriate?`,
    options: [r`Amoxicillin-clavulanate, because clavulanate blocks PBP2a`, r`Vancomycin, because it acts on a target other than the PBPs`, r`Cefazolin, because it resists hydrolysis by the lactamase`, r`High-dose penicillin, because PBP2a is a weak lactamase`],
    correctAnswer: 1,
    explanation: r`mecA encodes PBP2a, a transpeptidase that binds classic beta-lactams poorly, so the answer is a drug with a different target such as vancomycin. Clavulanate inhibits lactamases, not PBP2a, and since the resistance is an altered target, lactamase stability or a larger dose does not help.`,
  },
  [r`Why does combination antiretroviral therapy (multiple drug targets at once) suppress resistance?`]: {
    question: r`One patient with HIV takes drug A alone, adds drug B when A fails, then adds drug C when B fails. Why is this more likely to end in resistance than starting all three together?`,
    options: [r`Sequential use lets the three drugs inactivate one another in the blood`, r`Sequential use lets host cells lose the receptors the drugs act upon`, r`Sequential use lets resistance mutations be selected one at a time`, r`Sequential use lets the virus stop replicating and so evade the drugs`],
    correctAnswer: 2,
    explanation: r`Against one drug the virus needs only a single mutation, which arises readily and is then selected; the next drug then needs only one more. Given together, the drugs require all the mutations in one genome at once, which is extremely unlikely, and suppressed replication stops stepwise accumulation.`,
  },
  [r`The lowest drug concentration preventing visible growth is the {{c1::MIC}}; the MBC is the lowest killing 99.9 percent of the inoculum.`]: {
    question: r`Against one isolate, drug A has an MIC of 2 μg/mL and an MBC of 4 μg/mL, while drug B has an MIC of 2 μg/mL and an MBC of 64 μg/mL. Which is the better choice for a patient with almost no neutrophils, and why?`,
    options: [r`Drug A, because its MBC is close to its MIC, so it kills`, r`Drug B, because its MBC is far above its MIC, so it kills`, r`Either drug, because equal MICs mean equal killing power`, r`Drug B, because a higher MBC means more potency per dose`],
    correctAnswer: 0,
    explanation: r`The MIC is the lowest concentration preventing visible growth and the MBC is the lowest killing 99.9 percent. An MBC close to the MIC marks a cidal drug, which a patient without neutrophils needs. A large gap means drug B only holds growth at usable levels, and equal MICs say nothing about killing.`,
  },
  [r`A patient relapses after therapy, yet the recovered isolate has the same MIC as before. Resistance or tolerance?`]: {
    question: r`A drug kills all but 0.01 percent of a culture. The survivors are regrown without drug and exposed again: once more all but 0.01 percent die, and the MIC is unchanged. What are the survivors?`,
    options: [r`Resistant mutants: a heritable change that raises the MIC`, r`Plasmid recipients: cells that gained a new resistance gene`, r`Efflux mutants: a heritable pump change that raises the MIC`, r`Persister cells: dormant survivors with no genetic change`],
    correctAnswer: 3,
    explanation: r`The descendants are just as susceptible as the original culture and the MIC has not moved, so nothing heritable changed: the survivors were dormant persisters, which is tolerance. Any true resistance mechanism would raise the MIC and be passed on, so most of the regrown culture would survive.`,
  },
  [r`Why does resistance sometimes decline in a hospital after an antibiotic is withdrawn from the formulary?`]: {
    question: r`A resistant strain and its susceptible parent are mixed 1:1 in drug-free broth. After 50 generations the resistant strain makes up only 5 percent of the culture. What does this show?`,
    options: [r`Resistance genes are passed to the susceptible strain`, r`Resistance carries a fitness cost when no drug is present`, r`Resistance mutations revert whenever the drug is removed`, r`Resistance gives a growth advantage without any drug`],
    correctAnswer: 1,
    explanation: r`With no drug present the resistant strain is outgrown, which shows that its resistance mechanism slows it down: a fitness cost. Gene transfer would raise the resistant share, reversion is not what a competition experiment measures, and a growth advantage would have made the resistant strain dominant.`,
  },
  [r`Why is a bactericidal agent required in endocarditis, meningitis, and febrile neutropenia?`]: {
    question: r`Bacteria inside a heart-valve vegetation are treated with a bacteriostatic drug. Growth halts, but the infection returns when the drug is stopped. Why?`,
    options: [r`Phagocytes are destroyed by the static drug before reaching the cells`, r`Static drugs cannot dissolve in the blood flowing past a heart valve`, r`Phagocytes cannot enter the avascular fibrin to clear the halted cells`, r`Halted cells quickly mutate to degrade the static drug inside fibrin`],
    correctAnswer: 2,
    explanation: r`A static drug depends on the immune system to remove the organisms it has stopped, but a vegetation is avascular fibrin that phagocytes cannot penetrate, so live bacteria remain and regrow. That is why a cidal drug is required there. The other choices invent drug effects that do not occur.`,
  },
  [r`If resistance to each of three HIV drugs arises at $10^{-5}$ per replication, why does triple therapy work?`]: {
    question: r`In a patient with HIV, resistance to drug A arises at $10^{-4}$ per replication and resistance to drug B at $10^{-5}$ per replication, independently. What is the chance that one replication produces a genome resistant to both?`,
    options: [r`$10^{-20}$`, r`$10^{-9}$`, r`$10^{-4}$`, r`$10^{-1}$`],
    correctAnswer: 1,
    explanation: r`Independent probabilities multiply, so the exponents add: $10^{-4} \times 10^{-5} = 10^{-9}$. Multiplying the exponents gives $10^{-20}$, taking only the more likely mutation gives $10^{-4}$, and dividing one rate by the other gives $10^{-1}$. This small product is why combination therapy holds.`,
  },
  [r`In Kirby-Bauer disk diffusion, a larger zone of inhibition does not directly mean a more potent drug. Why?`]: {
    question: r`In a disk diffusion test of one isolate, drug A gives a 30 mm zone and drug B gives an 18 mm zone. Drug A counts as susceptible only at 35 mm or more; drug B counts as susceptible at 15 mm or more. How should the result be read?`,
    options: [r`Susceptible to B but not to A, by each drug's own breakpoint`, r`Susceptible to A but not to B, since A has the larger zone`, r`Susceptible to both, since each drug produced a clear zone`, r`Resistant to both, since neither zone reached 35 mm across`],
    correctAnswer: 0,
    explanation: r`Zone size depends on how fast each drug diffuses and how much the disk holds, so each zone is judged only against that drug's own breakpoint: 18 mm passes B's 15 mm cutoff and 30 mm misses A's 35 mm cutoff. Comparing the two zones directly, or applying one cutoff to both drugs, is the mistake.`,
  },
  [r`Amphotericin B binds ergosterol directly while azoles inhibit its {{c1::synthesis}} at a fungal cytochrome P450 step.`]: {
    question: r`A patient takes a medication that is cleared by liver cytochrome P450 enzymes. After an antifungal is started, the blood level of that medication rises sharply. Which antifungal is most likely responsible, and why?`,
    options: [r`Amphotericin B, because it inhibits human P450 enzymes too`, r`Amphotericin B, because it blocks ergosterol synthesis`, r`An azole, because it forms pores in liver cell membranes`, r`An azole, because it inhibits human P450 enzymes as well`],
    correctAnswer: 3,
    explanation: r`Azoles block ergosterol synthesis at a fungal cytochrome P450 step and also inhibit human P450 enzymes, so they raise the levels of other drugs. Amphotericin B binds ergosterol directly and forms pores; its typical harm is kidney injury, not drug interactions.`,
  },
  [r`Empiric therapy starts broad and is narrowed once culture returns, a practice called {{c1::de-escalation}}.`]: {
    question: r`A patient with sepsis is started on two broad-spectrum antibiotics after blood cultures are drawn. Two days later the patient is improving and the culture grows E. coli susceptible to a narrow-spectrum drug. What is the best next step?`,
    options: [r`Continue both broad agents until the full course is complete`, r`Add a third broad agent to prevent resistance from emerging`, r`Switch to the narrow agent that covers the identified organism`, r`Stop all antibiotics because the culture result is now known`],
    correctAnswer: 2,
    explanation: r`Broad empiric therapy protects the patient while the cause is unknown; once the culture identifies a susceptible organism, therapy is narrowed, which is de-escalation. Narrowing spares normal flora and lowers resistance selection and toxicity, while stopping entirely would leave the infection untreated.`,
  },
  [r`Beta-lactam efficacy tracks {{c1::time above MIC}}, whereas aminoglycoside efficacy tracks peak concentration.`]: {
    question: r`The same total daily dose of a beta-lactam is given in two ways. Regimen 1, one large daily dose, keeps the level above the MIC for 20 percent of the day. Regimen 2, four divided doses, keeps it above the MIC for 70 percent of the day. Which should work better?`,
    options: [r`Regimen 1, because beta-lactam killing depends on the peak level`, r`Regimen 2, because beta-lactam killing depends on time above MIC`, r`Regimen 1, because beta-lactams have a long postantibiotic effect`, r`Either one, because killing depends only on the total daily dose`],
    correctAnswer: 1,
    explanation: r`Beta-lactam efficacy follows the time the concentration stays above the MIC, so frequent dosing or extended infusion works better. Peak-dependent killing with a postantibiotic effect describes aminoglycosides, which is why those drugs are given as one large daily dose.`,
  },
  [r`Why do sulfonamides and trimethoprim harm bacteria but not humans, and why are they combined?`]: {
    question: r`Against one organism, sulfamethoxazole alone only stops growth and trimethoprim alone only stops growth, but together they kill at lower concentrations of each. What best explains this?`,
    options: [r`They block two successive steps of one bacterial pathway`, r`They block the same enzyme at two separate binding sites`, r`They block one step each in two unrelated bacterial pathways`, r`One blocks the pump that would otherwise export the other`],
    correctAnswer: 0,
    explanation: r`The sulfonamide blocks dihydropteroate synthase and trimethoprim blocks dihydrofolate reductase, two consecutive steps of bacterial folate synthesis, and this sequential blockade is synergistic. They act on different enzymes of the same pathway, and neither is an efflux inhibitor.`,
  },
  [r`An isolate is resistant to amoxicillin but susceptible to amoxicillin-clavulanate. What mechanism is present?`]: {
    question: r`A laboratory reports an E. coli isolate as resistant to ampicillin but susceptible to ampicillin combined with a beta-lactamase inhibitor. What does this imply about the isolate's penicillin-binding proteins?`,
    options: [r`They no longer bind the drug; the inhibitor takes their place`, r`They are overproduced; the inhibitor lowers their number`, r`They are absent; the inhibitor kills through a second target`, r`They still bind the drug; an enzyme was destroying it first`],
    correctAnswer: 3,
    explanation: r`Susceptibility restored by a lactamase inhibitor shows that the resistance came from an enzyme destroying the drug, so the target proteins themselves are normal. Altered binding proteins would leave the isolate resistant to the combination too, and the inhibitor has little antibacterial activity of its own.`,
  },
  [r`Pairing a bacteriostatic drug with a beta-lactam can be {{c1::antagonistic}} because cell-wall agents require active growth.`]: {
    question: r`Penicillin alone kills 99.9 percent of a pneumococcal culture in 6 hours. Chloramphenicol alone stops growth but kills almost none. Given together, they kill only 90 percent in 6 hours. What is this drug interaction called?`,
    options: [r`Additivity`, r`Synergism`, r`Antagonism`, r`Indifference`],
    correctAnswer: 2,
    explanation: r`The pair kills less than penicillin does alone, which is antagonism: the static drug halts growth, and a wall-directed drug needs growing cells. Synergism and additivity would mean more killing than the best single drug, and indifference would mean the same killing as penicillin alone.`,
  },
  [r`Adding a beta-lactam makes an aminoglycoside far more effective against enterococci. Explain the synergy.`]: {
    question: r`Enterococci are exposed to gentamicin with or without ampicillin, and the amount of gentamicin inside the cells is measured. What is expected?`,
    options: [r`Lower with ampicillin, because wall damage speeds efflux`, r`Higher with ampicillin, because wall damage improves uptake`, r`Higher with ampicillin, because it blocks a modifying enzyme`, r`Unchanged, because ampicillin acts only on the 50S subunit`],
    correctAnswer: 1,
    explanation: r`Aminoglycosides enter enterococci poorly on their own. A beta-lactam damages the wall, so more aminoglycoside gets in and reaches the ribosome, which is the basis of the synergy. Ampicillin is a wall-directed drug: it does not act on the ribosome, on efflux or on modifying enzymes.`,
  },
  [r`MRSA resists every beta-lactam because it acquired {{c1::PBP2a}}, an altered penicillin-binding protein.`]: {
    question: r`A methicillin-resistant Staphylococcus aureus culture is exposed to oxacillin, a beta-lactam. Does peptidoglycan cross-linking continue, and why?`,
    options: [r`Yes, by PBP2a, which binds beta-lactams only poorly`, r`Yes, by a beta-lactamase, which cross-links the wall`, r`No, but the cell survives without any cross-links`, r`No, until an efflux pump has removed the oxacillin`],
    correctAnswer: 0,
    explanation: r`MRSA carries PBP2a, an altered transpeptidase that keeps cross-linking the wall because beta-lactams bind it poorly. A beta-lactamase destroys drug and does not build wall, a wall with no cross-links would fail, and efflux is not the mechanism here.`,
  },
  [r`Vancomycin-resistant enterococci replace the D-Ala-D-Ala terminus with D-Ala-D-Lac. Why is that so effective?`]: {
    question: r`Vancomycin at 2 μg/mL occupies most normal wall precursors. In a resistant enterococcus, the loss of one hydrogen bond lowers the drug's affinity for the precursor 1000-fold. Roughly what concentration would give the same occupancy?`,
    options: [r`About 0.002 μg/mL`, r`About 2 μg/mL`, r`About 20 μg/mL`, r`About 2000 μg/mL`],
    correctAnswer: 3,
    explanation: r`A 1000-fold weaker affinity needs about 1000 times more drug for the same binding: 2 × 1000 = 2000 μg/mL, far beyond any safe level, which is why one lost hydrogen bond defeats the drug. Dividing by 1000 gives 0.002, and the other values understate how large the loss of affinity is.`,
  },
  [r`Low-level resistance to several structurally unrelated antibiotics at once points to an upregulated {{c1::efflux pump}}.`]: {
    question: r`An isolate shows MICs raised about 4-fold for a fluoroquinolone, a tetracycline and chloramphenicol together. All three drugs are recovered chemically intact. What is the most likely single cause?`,
    options: [r`A point mutation in the DNA gyrase A subunit`, r`Acquisition of an extended-spectrum lactamase`, r`Upregulation of a broad-substrate efflux pump`, r`Methylation of the 23S rRNA in the 50S subunit`],
    correctAnswer: 2,
    explanation: r`Modest resistance to several unrelated drug classes at once points to a multidrug efflux pump, which exports chemically diverse drugs. A gyrase mutation affects only quinolones, a lactamase only beta-lactams, and 23S rRNA methylation only drugs that bind that 50S site.`,
  },
  [r`Aminoglycosides cause nephrotoxicity and ototoxicity despite targeting the 30S subunit. Reconcile this.`]: {
    question: r`A patient receiving gentamicin has blood levels of the drug checked regularly. What reasoning lies behind this monitoring?`,
    options: [r`Selectivity is absolute: levels only show whether the patient took the dose`, r`Selectivity is relative: the drug builds up in renal tubule and cochlear cells`, r`Selectivity is absent: the drug binds 80S and 70S ribosomes equally tightly`, r`Selectivity is reversed: the drug prefers human 40S subunits at low levels`],
    correctAnswer: 1,
    explanation: r`Aminoglycosides prefer the bacterial 30S subunit, but selective toxicity is relative. The drugs accumulate in kidney tubule cells and inner-ear hair cells and injure them, partly through mitochondrial ribosomes, so levels are watched. They do not bind human cytoplasmic ribosomes as well as bacterial ones.`,
  },
}
